import { IngestPipeline } from "@514labs/moose-lib";

export interface UserActivity {
  event_id: string;
  event_ts: Date;
  user_id: string;
  action: string;
  duration_ms: number;
}

// Configure table with optimal ordering for date range and user queries
export const UserActivityPipeline = new IngestPipeline<UserActivity>("UserActivity", {
  table: {
    // Order by timestamp first for date range queries, then user_id for user-based analytics
    orderByFields: ["event_ts", "user_id"]
  },
  stream: true,
  ingestApi: true,
});

